using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 defaults to "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries reference c.Discriminator, so we pin the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format simplified.
            // EF Core 9 stores id as just the key value ("123").
            // Existing documents use the EF8 format "Product|123".
            // Preserve it so reads of existing data keep working.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

            // BREAKING CHANGE 3 — HasIndex is no longer supported.
            // The Cosmos provider now throws at model validation.
            // Removed: entity.HasIndex(p => p.Sku);
            // Cosmos indexes are managed via the container's indexing policy
            // in the Azure Portal or via IaC, not through EF.
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

