class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we pinned the discriminator
        // property name to "Discriminator" in OnModelCreating.
        // Without that override, EF9 would write "$type" and this query
        // would silently return zero rows against existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // BREAKING CHANGE 4 — Synchronous LINQ APIs removed.
        // The Cosmos provider in EF9 no longer supports ToList(), First(),
        // Single(), etc. All queries must use their async counterparts.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

